static char words[MAXN][MAXLEN];
static bool visited[MAXN];
static int parents[MAXN][MAXN];
static int parentCount[MAXN];
static int path[MAXN];
static int pathLen;
static char results[MAXP][MAXN][MAXLEN];
static int resultLen[MAXP];
static int resultCount;

static char *dupStr(const char *s) {
  int len = (int)strlen(s);
  char *r = (char *)malloc(len + 1);
  memcpy(r, s, len + 1);
  return r;
}

static int oneDiff(const char *a, const char *b) {
  if (strlen(a) != strlen(b)) return 0;
  int diff = 0;
  for (int i = 0; a[i]; i++) {
    if (a[i] != b[i]) {
      diff++;
      if (diff > 1) return 0;
    }
  }
  return diff == 1;
}

static void dfs(int u, int beginIdx) {
  path[pathLen++] = u;
  if (u == beginIdx) {
    if (resultCount < MAXP) {
      resultLen[resultCount] = pathLen;
      for (int i = 0; i < pathLen; i++) {
        strcpy(results[resultCount][i], words[path[pathLen - 1 - i]]);
      }
      resultCount++;
    }
    pathLen--;
    return;
  }
  for (int i = 0; i < parentCount[u]; i++) {
    dfs(parents[u][i], beginIdx);
  }
  pathLen--;
}

char ***findLadders(char *beginWord, char *endWord, char **wordList, int wordListSize,
                    int *returnSize, int **returnColumnSizes) {
  resultCount = 0;
  pathLen = 0;

  int m = 0;
  strcpy(words[m++], beginWord);
  for (int i = 0; i < wordListSize; i++) {
    strcpy(words[m++], wordList[i]);
  }

  int endIdx = -1;
  for (int i = 1; i < m; i++) {
    if (strcmp(words[i], endWord) == 0) {
      endIdx = i;
      break;
    }
  }

  *returnSize = 0;
  *returnColumnSizes = NULL;
  if (endIdx == -1) return NULL;

  for (int i = 0; i < m; i++) {
    visited[i] = false;
    parentCount[i] = 0;
  }
  visited[0] = true;

  static int curLevel[MAXN];
  static int nextLevel[MAXN];
  int curCount = 1;
  curLevel[0] = 0;
  bool found = false;

  while (curCount > 0 && !found) {
    int nextCount = 0;
    for (int ci = 0; ci < curCount; ci++) {
      int u = curLevel[ci];
      for (int v = 0; v < m; v++) {
        if (v == u || visited[v]) continue;
        if (!oneDiff(words[u], words[v])) continue;
        parents[v][parentCount[v]++] = u;
        bool present = false;
        for (int t = 0; t < nextCount; t++) {
          if (nextLevel[t] == v) {
            present = true;
            break;
          }
        }
        if (!present) nextLevel[nextCount++] = v;
      }
    }
    for (int t = 0; t < nextCount; t++) {
      visited[nextLevel[t]] = true;
      if (nextLevel[t] == endIdx) found = true;
    }
    for (int t = 0; t < nextCount; t++) {
      curLevel[t] = nextLevel[t];
    }
    curCount = nextCount;
  }

  if (!found) return NULL;

  dfs(endIdx, 0);

  char ***res = (char ***)malloc(sizeof(char **) * resultCount);
  int *colSizes = (int *)malloc(sizeof(int) * resultCount);
  for (int i = 0; i < resultCount; i++) {
    res[i] = (char **)malloc(sizeof(char *) * resultLen[i]);
    for (int j = 0; j < resultLen[i]; j++) {
      res[i][j] = dupStr(results[i][j]);
    }
    colSizes[i] = resultLen[i];
  }

  *returnSize = resultCount;
  *returnColumnSizes = colSizes;
  return res;
}

class Solution {
  unordered_map<string, vector<string>> parents;
  unordered_set<string> dict;

  void dfs(const string &word, const string &beginWord, vector<string> &path,
           vector<vector<string>> &res) {
    if (word == beginWord) {
      vector<string> r(path.rbegin(), path.rend());
      res.push_back(r);
      return;
    }
    for (const string &p : parents[word]) {
      path.push_back(p);
      dfs(p, beginWord, path, res);
      path.pop_back();
    }
  }

public:
  vector<vector<string>> findLadders(string beginWord, string endWord, vector<string> &wordList) {
    vector<vector<string>> res;
    dict = unordered_set<string>(wordList.begin(), wordList.end());
    parents.clear();
    if (!dict.count(endWord)) return res;

    unordered_set<string> visited;
    visited.insert(beginWord);
    vector<string> level = {beginWord};
    bool found = false;

    while (!level.empty() && !found) {
      vector<string> next;
      unordered_set<string> nextSet;
      for (const string &word : level) {
        string w = word;
        for (size_t j = 0; j < w.size(); j++) {
          char origin = w[j];
          for (char c = 'a'; c <= 'z'; c++) {
            if (c == origin) continue;
            w[j] = c;
            if (dict.count(w) && !visited.count(w)) {
              if (nextSet.insert(w).second) next.push_back(w);
              parents[w].push_back(word);
              if (w == endWord) found = true;
            }
          }
          w[j] = origin;
        }
      }
      for (const string &w : next) visited.insert(w);
      level = next;
    }

    if (!found) return res;

    vector<string> path = {endWord};
    dfs(endWord, beginWord, path, res);
    return res;
  }
};

func findLadders(beginWord string, endWord string, wordList []string) [][]string {
	res := [][]string{}
	dict := make(map[string]bool, len(wordList))
	for _, w := range wordList {
		dict[w] = true
	}
	if !dict[endWord] {
		return res
	}

	parents := map[string][]string{}
	visited := map[string]bool{beginWord: true}
	level := []string{beginWord}
	found := false

	for len(level) > 0 && !found {
		next := []string{}
		nextSet := map[string]bool{}
		for _, word := range level {
			bs := []byte(word)
			for j := 0; j < len(bs); j++ {
				origin := bs[j]
				for c := byte('a'); c <= 'z'; c++ {
					if c == origin {
						continue
					}
					bs[j] = c
					cand := string(bs)
					if dict[cand] && !visited[cand] {
						if !nextSet[cand] {
							nextSet[cand] = true
							next = append(next, cand)
						}
						parents[cand] = append(parents[cand], word)
						if cand == endWord {
							found = true
						}
					}
				}
				bs[j] = origin
			}
		}
		for _, w := range next {
			visited[w] = true
		}
		level = next
	}

	if !found {
		return res
	}

	var dfs func(word string, path []string)
	dfs = func(word string, path []string) {
		if word == beginWord {
			r := make([]string, len(path))
			for i := range path {
				r[i] = path[len(path)-1-i]
			}
			res = append(res, r)
			return
		}
		for _, p := range parents[word] {
			np := make([]string, len(path)+1)
			copy(np, path)
			np[len(path)] = p
			dfs(p, np)
		}
	}
	dfs(endWord, []string{endWord})

	return res
}

class Solution {
  private Map<String, List<String>> parents = new HashMap<>();

  private void dfs(String word, String beginWord, List<String> path, List<List<String>> res) {
    if (word.equals(beginWord)) {
      List<String> r = new ArrayList<>(path);
      Collections.reverse(r);
      res.add(r);
      return;
    }
    List<String> ps = parents.getOrDefault(word, Collections.emptyList());
    for (String p : ps) {
      path.add(p);
      dfs(p, beginWord, path, res);
      path.remove(path.size() - 1);
    }
  }

  public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
    List<List<String>> res = new ArrayList<>();
    Set<String> dict = new HashSet<>(wordList);
    if (!dict.contains(endWord)) {
      return res;
    }

    parents.clear();
    Set<String> visited = new HashSet<>();
    visited.add(beginWord);
    List<String> level = new ArrayList<>();
    level.add(beginWord);
    boolean found = false;

    while (!level.isEmpty() && !found) {
      List<String> next = new ArrayList<>();
      Set<String> nextSet = new HashSet<>();
      for (String word : level) {
        char[] arr = word.toCharArray();
        for (int j = 0; j < arr.length; j++) {
          char origin = arr[j];
          for (char c = 'a'; c <= 'z'; c++) {
            if (c == origin) {
              continue;
            }
            arr[j] = c;
            String cand = new String(arr);
            if (dict.contains(cand) && !visited.contains(cand)) {
              if (nextSet.add(cand)) {
                next.add(cand);
              }
              parents.computeIfAbsent(cand, k -> new ArrayList<>()).add(word);
              if (cand.equals(endWord)) {
                found = true;
              }
            }
          }
          arr[j] = origin;
        }
      }
      visited.addAll(next);
      level = next;
    }

    if (!found) {
      return res;
    }

    List<String> path = new ArrayList<>();
    path.add(endWord);
    dfs(endWord, beginWord, path, res);
    return res;
  }
}

class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
        word_set = set(wordList)
        res: List[List[str]] = []
        if endWord not in word_set:
            return res

        parents = defaultdict(list)
        visited = {beginWord}
        level = [beginWord]
        found = False

        while level and not found:
            next_set = set()
            next_level = []
            for word in level:
                for i in range(len(word)):
                    for ch in "abcdefghijklmnopqrstuvwxyz":
                        if ch == word[i]:
                            continue
                        cand = word[:i] + ch + word[i + 1:]
                        if cand in word_set and cand not in visited:
                            if cand not in next_set:
                                next_set.add(cand)
                                next_level.append(cand)
                            parents[cand].append(word)
                            if cand == endWord:
                                found = True
            visited |= next_set
            level = next_level

        if not found:
            return res

        def dfs(word: str, path: List[str]) -> None:
            if word == beginWord:
                res.append(path[::-1])
                return
            for p in parents[word]:
                dfs(p, path + [p])

        dfs(endWord, [endWord])
        return res

use std::collections::{HashMap, HashSet};

impl Solution {
  fn dfs(
    word: &str,
    begin: &str,
    parents: &HashMap<String, Vec<String>>,
    path: &mut Vec<String>,
    res: &mut Vec<Vec<String>>,
  ) {
    if word == begin {
      let mut r = path.clone();
      r.reverse();
      res.push(r);
      return;
    }
    if let Some(ps) = parents.get(word) {
      for p in ps {
        path.push(p.clone());
        Solution::dfs(p, begin, parents, path, res);
        path.pop();
      }
    }
  }

  pub fn find_ladders(begin_word: String, end_word: String, word_list: Vec<String>) -> Vec<Vec<String>> {
    let dict: HashSet<String> = word_list.into_iter().collect();
    let mut res: Vec<Vec<String>> = Vec::new();
    if !dict.contains(&end_word) {
      return res;
    }

    let mut parents: HashMap<String, Vec<String>> = HashMap::new();
    let mut visited: HashSet<String> = HashSet::new();
    visited.insert(begin_word.clone());
    let mut level: Vec<String> = vec![begin_word.clone()];
    let mut found = false;

    while !level.is_empty() && !found {
      let mut next: Vec<String> = Vec::new();
      let mut next_set: HashSet<String> = HashSet::new();
      for word in &level {
        let bytes = word.clone().into_bytes();
        for j in 0..bytes.len() {
          for c in b'a'..=b'z' {
            if c == bytes[j] {
              continue;
            }
            let mut nb = bytes.clone();
            nb[j] = c;
            let cand = String::from_utf8(nb).unwrap();
            if dict.contains(&cand) && !visited.contains(&cand) {
              if next_set.insert(cand.clone()) {
                next.push(cand.clone());
              }
              parents.entry(cand.clone()).or_insert_with(Vec::new).push(word.clone());
              if cand == end_word {
                found = true;
              }
            }
          }
        }
      }
      for w in &next {
        visited.insert(w.clone());
      }
      level = next;
    }

    if !found {
      return res;
    }

    let mut path: Vec<String> = vec![end_word.clone()];
    Solution::dfs(&end_word, &begin_word, &parents, &mut path, &mut res);
    res
  }
}

const findLadders = (beginWord: string, endWord: string, wordList: string[]): string[][] => {
  const res: string[][] = [];
  const dict = new Set<string>(wordList);
  if (!dict.has(endWord)) return res;

  const parents = new Map<string, string[]>();
  const visited = new Set<string>([beginWord]);
  let level: string[] = [beginWord];
  let found = false;
  const base = 'a'.charCodeAt(0);

  while (level.length > 0 && !found) {
    const next: string[] = [];
    const nextSet = new Set<string>();
    for (const word of level) {
      for (let j = 0; j < word.length; j++) {
        for (let k = 0; k < 26; k++) {
          const c = String.fromCharCode(base + k);
          if (c === word[j]) continue;
          const cand = word.slice(0, j) + c + word.slice(j + 1);
          if (dict.has(cand) && !visited.has(cand)) {
            if (!nextSet.has(cand)) {
              nextSet.add(cand);
              next.push(cand);
            }
            if (!parents.has(cand)) parents.set(cand, []);
            parents.get(cand)!.push(word);
            if (cand === endWord) found = true;
          }
        }
      }
    }
    for (const w of next) visited.add(w);
    level = next;
  }

  if (!found) return res;

  const dfs = (word: string, path: string[]): void => {
    if (word === beginWord) {
      res.push([...path].reverse());
      return;
    }
    for (const p of parents.get(word) || []) {
      dfs(p, [...path, p]);
    }
  };
  dfs(endWord, [endWord]);

  return res;
};
